insert into bases (key, name, tagline, summary, guidance, is_variation_of, fill_ingredient_id, sort_order) values ('everyday', 'Everyday creamy', 'Best all-rounder', 'For vanilla, caramel, coffee and biscuit flavours.', 'The default base. Blend the protein powder and xanthan gum together dry before adding liquid so the xanthan disperses without clumping.', null, (select id from ingredients where slug = 'semi-skimmed-milk'), 1) on conflict (key) do update set name = excluded.name, tagline = excluded.tagline, summary = excluded.summary, guidance = excluded.guidance, is_variation_of = excluded.is_variation_of, fill_ingredient_id = excluded.fill_ingredient_id, sort_order = excluded.sort_order;
insert into bases (key, name, tagline, summary, guidance, is_variation_of, fill_ingredient_id, sort_order) values ('fruit', 'Fruit and yoghurt', 'Fruit & light days', 'More room for banana, mango, berries or cooked apple.', 'Leaves headroom for 100–160g of fruit. Blend fruit completely smooth to avoid icy pockets. Xanthan is optional for banana but useful for berries.', null, (select id from ingredients where slug = 'semi-skimmed-milk'), 2) on conflict (key) do update set name = excluded.name, tagline = excluded.tagline, summary = excluded.summary, guidance = excluded.guidance, is_variation_of = excluded.is_variation_of, fill_ingredient_id = excluded.fill_ingredient_id, sort_order = excluded.sort_order;
insert into bases (key, name, tagline, summary, guidance, is_variation_of, fill_ingredient_id, sort_order) values ('choc', 'Chocolate creamy', 'Chocolate recipes', 'The Everyday creamy base, using chocolate protein and cocoa.', 'Cocoa quantity comes from the individual recipe. Dutch-process cocoa gives a rounder, darker flavour.', (select id from bases where key = 'everyday'), (select id from ingredients where slug = 'semi-skimmed-milk'), 3) on conflict (key) do update set name = excluded.name, tagline = excluded.tagline, summary = excluded.summary, guidance = excluded.guidance, is_variation_of = excluded.is_variation_of, fill_ingredient_id = excluded.fill_ingredient_id, sort_order = excluded.sort_order;
insert into bases (key, name, tagline, summary, guidance, is_variation_of, fill_ingredient_id, sort_order) values ('dessert', 'Dessert-style', 'Richer flavours', 'Quark and a little light cream cheese for a denser, more dessert-like finish.', 'Use when the recipe specifies Dessert-style. Fat-free cottage cheese can replace quark gram for gram, but blend it completely smooth first.', null, (select id from ingredients where slug = 'semi-skimmed-milk'), 4) on conflict (key) do update set name = excluded.name, tagline = excluded.tagline, summary = excluded.summary, guidance = excluded.guidance, is_variation_of = excluded.is_variation_of, fill_ingredient_id = excluded.fill_ingredient_id, sort_order = excluded.sort_order;
insert into bases (key, name, tagline, summary, guidance, is_variation_of, fill_ingredient_id, sort_order) values ('cheesecake', 'Cheesecake', 'Cheesecake flavours', 'The dessert-style base, tuned for tangy cheesecake flavours.', 'For the cleanest cheesecake texture, quark is the first choice over cottage cheese. A squeeze of lemon juice sharpens the tang on any flavour in this base.', (select id from bases where key = 'dessert'), (select id from ingredients where slug = 'semi-skimmed-milk'), 5) on conflict (key) do update set name = excluded.name, tagline = excluded.tagline, summary = excluded.summary, guidance = excluded.guidance, is_variation_of = excluded.is_variation_of, fill_ingredient_id = excluded.fill_ingredient_id, sort_order = excluded.sort_order;
insert into bases (key, name, tagline, summary, guidance, is_variation_of, fill_ingredient_id, sort_order) values ('coconut', 'Coconut', 'Tropical flavours', 'The fruit base with part of the milk replaced by light coconut milk.', 'Light coconut milk tastes more convincing than coconut extract alone.', (select id from bases where key = 'fruit'), (select id from ingredients where slug = 'semi-skimmed-milk'), 6) on conflict (key) do update set name = excluded.name, tagline = excluded.tagline, summary = excluded.summary, guidance = excluded.guidance, is_variation_of = excluded.is_variation_of, fill_ingredient_id = excluded.fill_ingredient_id, sort_order = excluded.sort_order;
