insert into recipe_ingredients (recipe_id, ingredient_id, role, quantity, unit, display, optional, free_text, sort_order) select r.id, v.ingredient_id, v.role, v.quantity, v.unit, v.display, v.optional, v.free_text, v.sort_order from recipes r cross join (values ((select id from ingredients where slug = 'vanilla-bean-paste'), 'addition'::text, 5::numeric, 'g'::text, '1 tsp vanilla bean paste'::text, false::boolean, null::text, 0::int), ((select id from ingredients where slug = 'fine-salt'), 'addition'::text, 0.5::numeric, 'g'::text, 'Pinch of fine salt'::text, false::boolean, null::text, 1::int), ((select id from ingredients where slug = 'wafer-pieces'), 'mixin'::text, 5::numeric, 'g'::text, '5g wafer pieces'::text, true::boolean, null::text, 2::int)) as v(ingredient_id, role, quantity, unit, display, optional, free_text, sort_order) where r.slug = 'vanilla-custard' and r.is_seed = true and not exists (select 1 from recipe_ingredients ri where ri.recipe_id = r.id);
